    {"항목": "헬라 서신의 감사 형식", "내용": "당시 헬라 서신에서는 인사 후 신들에게 감사를 표하는 것이 일반적인 관례였다. 바울은 이 형식을 차용하되 대상을 성경의 하나님으로 바꾸었다", "목회적활용": "기독교 복음은 문화적 형식을 통해 전달된다. 형식을 복음적으로 변환하는 지혜가 효과적인 사역의 열쇠이다"}
