    {"대지": "서론", "내용": "빌립보에서 채찍질과 감옥을 경험한 바울이 데살로니가에서 더욱 담대히 복음을 전했다. 고난이 그를 막지 못했다. 오히려 담대함이 더 커졌다", "예화_적용": "담금질을 통해 강해지는 철처럼 고난이 사역자를 더 강하게 단련시킨다"},
    {"대지": "1대지: 고난을 통과한 사역자의 자격 (진실성)", "내용": "빌립보의 고난이 데살로니가 사역의 자격증이 되었다. 자신의 이익을 위해 사역한다면 고난 앞에서 도망간다. 고난 후에도 계속 사역함이 진정성의 증거이다", "예화_적용": "전투를 경험한 군인이 훈련소만 나온 군인보다 더 믿음직스럽다"},
    {"대지": "2대지: 하나님 안에서의 담대함 (근거)", "내용": "담대함의 근거는 하나님 안에서이다. 인간의 용기가 아닌 하나님의 능력에서 오는 담대함이다. 하나님이 함께하시면 담대해진다", "예화_적용": "작은 아이도 아버지 손을 잡으면 어두운 길을 담대히 걸어간다"},
    {"대지": "3대지: 싸움 중에 전하는 복음 (지속성)", "내용": "많은 싸움 가운데서도 복음을 전했다. 저항이 있다는 것이 사역을 멈출 이유가 아니라 더 담대히 전해야 할 이유이다", "예화_적용": "역풍이 강할수록 독수리는 더 높이 난다. 저항이 클수록 담대하게 전하는 복음이 더 멀리 간다"},
    {"대지": "결론", "내용": "오늘 우리 앞에 고난과 저항이 있는가? 하나님 안에서 더욱 담대해질 기회이다", "예화_적용": "오늘 마주친 어려움 앞에서 하나님의 손을 잡고 담대히 나아가자"}
