    {"상황": "과거의 상처와 수치로 사역을 두려워하는 분", "성경원리": "바울은 빌립보에서 심한 능욕을 당했으나 그것이 그를 멈추지 못했다. 과거의 상처가 현재의 사역을 막을 수 없다", "실제적용": "과거의 상처를 인정하되 그것이 정체성이 아님을 가르치라. 하나님 안에서의 담대함이 과거의 상처를 이긴다"},
    {"상황": "반대와 비난 때문에 복음 전하기가 두려운 분", "성경원리": "바울도 많은 싸움 가운데서 복음을 전했다. 저항이 있어도 담대히 전하는 것이 사역자의 사명이다", "실제적용": "두려움을 인정하고 함께 기도하라. 행 4:29처럼 담대하게 말씀 전할 용기를 구하도록 이끌라"}
