    {"상황": "거짓 교사에게 속아 상처받은 분", "성경원리": "거짓 교사는 간사와 궤계를 사용한다. 투명하고 순수한 사역자를 구별하는 기준은 동기와 삶이다", "실제적용": "상처를 인정하고 치유하는 과정을 함께 걷되 진정한 사역자와 거짓 사역자를 분별하는 기준을 말씀으로 가르치라"}
