    {"항목": "재정 투명성", "내용": "바울은 데살로니가에서 스스로 일하며 재정적 부담을 주지 않았다(살전 2:9). 이것이 탐심의 탈을 쓰지 않음의 실제적 증거였다. 재정 투명성이 사역자의 신뢰성을 높인다", "목회적활용": "사역자의 재정적 투명성이 복음의 신뢰성을 높인다. 돈 문제에서 깨끗함이 사역의 기본 조건이다"}
