    {"상황": "자신의 권리를 침해받아 억울한 분", "성경원리": "바울도 정당한 권리가 있었지만 포기했다. 때로 권리를 주장하는 것보다 포기하는 것이 더 큰 열매를 낳는다", "실제적용": "권리를 주장하는 것과 포기하는 것 중 어느 것이 하나님 나라를 더 세우는지 함께 분별하라. 경우에 따라 다를 수 있음을 인정하라"}
