    {"상황": "목회가 힘들어 지친 분", "성경원리": "유모도 지친다. 바울도 수고와 애씀이 있었다. 그러나 성도를 향한 사랑이 그 피로를 이겼다. 사랑이 동력이다", "실제적용": "지침을 인정하고 쉼을 권장하라. 동시에 성도를 향한 사랑을 다시 회복할 수 있도록 기도하고 지지하라"}
