    {"상황": "가족에게 헌신하지 못해 죄책감을 느끼는 분", "성경원리": "바울의 목숨까지 내어주는 사랑은 한 가지에만 적용된 것이 아니다. 사역과 가족 모두를 향한 사랑의 균형이 필요하다", "실제적용": "죄책감보다 사랑의 우선순위를 점검하도록 도우라. 가족도 하나님이 맡기신 사람들임을 상기시키고 구체적 시간 분배를 함께 생각하라"}
