    {"원어": "δικαίως (디카이오스)", "의미_문법": "옳게/의롭게 - 부사. 사람들에 대한 공의, 올바른 관계", "설교포인트": "옳게 산다는 것은 사람들과의 관계에서 공의롭게 행하는 것이다. 거룩함이 하나님과의 관계라면 의로움은 사람과의 관계이다"},
    {"원어": "ἀμέμπτως (아멤프토스)", "의미_문법": "흠 없이 - 부사. 비난받을 것이 없이, 책잡힐 것 없이", "설교포인트": "흠 없이 산다는 것은 행동에서 책잡힐 것이 없는 것이다. 세 가지 부사가 함께 사역자의 전인격적 모범을 그린다"}
