    {"새찬송가": "491", "통일찬송가": "548", "제목": "내 삶의 주인은 누구", "선정이유": "하나님 나라의 시민으로 합당하게 살겠다는 결단을 담는다"},
    {"새찬송가": "560", "통일찬송가": "412", "제목": "하나님의 나팔 소리", "선정이유": "하나님 나라의 완성을 기다리며 깨어 사는 성도를 격려한다"}
