    {"상황": "성경을 읽어도 변화가 없다고 느끼는 분", "성경원리": "말씀은 믿는 자 속에서 역사한다. 역사가 느껴지지 않아도 말씀을 받아들이면 하나님이 보이지 않는 곳에서 역사하고 계신다", "실제적용": "느낌이 아닌 믿음으로 말씀을 받아들이도록 격려하라. 씨앗이 자라는 것이 보이지 않아도 자라고 있음을 가르치라"}
