    {"교리": "고난의 보편성과 연대", "설명": "그리스도를 따르는 자들이 고난을 받는 것은 보편적 패턴이다(딤후 3:12). 이 보편성이 교회들 사이의 연대를 만들어낸다. 같은 고난을 겪는 자들이 서로의 진정한 지지자가 된다", "관련구절": "빌 1:29, 벧전 4:12-13, 롬 8:17, 행 14:22"}
