    {"영어원문": "As they suffered of the Jews, even so ye have suffered of your own countrymen — the same cause, the same cross, though from different hands.", "한국어번역": "저희가 유대인들에게 고난받음같이 너희도 동족에게 동일한 고난을 받았느니라 — 같은 이유, 같은 십자가이다. 다만 다른 손에서 온 것일 뿐이다.", "핵심통찰": "고난의 원인과 성격은 같지만 가해자가 다를 뿐이다. 그리스도를 위한 고난은 어디서나 동일한 패턴을 가진다"}
