    {"구분": "나오미와 룻의 상호적 사랑", "내용": "나오미가 룻을 사랑하고 룻이 나오미를 사랑한 상호적 사랑(룻 1:14-18)이 사역자와 성도 사이의 상호적 사랑의 구약 원형이다", "그리스도연결": "우리가 하나님을 사랑하는 것은 그분이 먼저 우리를 사랑하셨기 때문이다(요일 4:19). 상호적 사랑이 그리스도 안에서 완성된다"}
