    {"영어원문": "You have good remembrance of us always, desiring greatly to see us — mutual affection between ministers and people is a great blessing.", "한국어번역": "너희가 항상 우리를 잘 생각하고 간절히 보고자 한다 — 사역자와 성도 사이의 상호적 애정은 큰 복이다.", "핵심통찰": "사역자와 성도 사이의 상호적 그리움이 건강한 교회의 증거이다"}
