    {"상황": "사역자가 어려운 것을 보고 어떻게 도와야 할지 모르는 성도", "성경원리": "데살로니가 성도들의 믿음이 바울을 위로했다. 성도가 할 수 있는 최고의 위로는 믿음으로 굳건히 서는 것이다. 또한 기도와 격려의 말도 위로가 된다", "실제적용": "기도로 사역자를 지지하도록 권면하라. 또한 격려의 말, 감사의 표현이 사역자에게 얼마나 큰 위로가 되는지 가르치라"}
