    {"교리": "성도와 사역자의 상호 생명성", "설명": "성도가 굳게 서면 사역자가 산다는 것은 성도와 사역자가 영적으로 연결된 생명 공동체임을 보여준다. 한 지체의 건강이 전체의 건강이다", "관련구절": "고전 12:26, 롬 12:15, 살전 2:19-20, 빌 4:1"}
