    {"구분": "다윗이 굳게 설 때 이스라엘이 살았음", "내용": "다윗이 하나님 안에서 굳건히 서 있을 때 이스라엘 전체가 복을 받았다. 지도자의 믿음이 공동체에 영향을 미치는 것이 구약의 패턴이다", "그리스도연결": "그리스도께서 아버지 앞에 굳게 서심으로 우리가 살게 되었다. 우리가 그리스도 안에 굳게 서는 것이 이것의 반영이다"}
