    {"새찬송가": "180", "통일찬송가": "175", "제목": "주 예수 오시겠네", "선정이유": "모든 성도와 함께 강림하실 주님을 기다리는 신앙을 노래한다"},
    {"새찬송가": "213", "통일찬송가": "213", "제목": "내 삶을 깨끗하게", "선정이유": "재림을 준비하며 거룩하게 살기를 구하는 성도의 기도이다"},
    {"새찬송가": "176", "통일찬송가": "171", "제목": "왕이신 내 주를 높이어라", "선정이유": "모든 성도와 함께 강림하실 왕이신 주님을 경배한다"}
