    {"원어": "ἀρέσκειν (아레스케인)", "의미_문법": "기쁘시게 하다 - 동사 현재 능동 부정사. 기쁘게 하다, 만족하게 하다", "설교포인트": "행함의 목표가 하나님을 기쁘시게 하는 것이다. 사람의 눈이 아닌 하나님의 눈을 의식하는 삶이 성화의 동기이다"}
