    {"대지": "서론", "내용": "바울은 명령을 새로 주는 것이 아니라 이미 알고 있는 것을 상기시킨다. 주 예수로 말미암은 명령이다. 이 권위가 명령에 구속력을 부여한다", "예화_적용": "왕의 편지를 전달하는 신하처럼, 바울은 주 예수의 명령을 전달하는 도구이다. 권위는 바울이 아닌 주 예수께 있다"},
    {"대지": "1대지: 주 예수로 말미암은 명령의 권위 (권위)", "내용": "명령의 권위가 주 예수로 말미암는다. 이 권위가 명령에 무게를 준다. 그리스도의 이름으로 전해지는 말씀은 그분의 권위를 갖는다", "예화_적용": "왕의 직인이 찍힌 문서는 왕의 권위를 갖는다. 주 예수의 이름으로 전해지는 말씀은 그분의 권위를 갖는다"},
    {"대지": "2대지: 알고 있음의 책임 (지식의 책임)", "내용": "아느니라는 선언이 책임을 더 크게 한다. 알면서 행하지 않는 것이 더 큰 죄이다. 알고 있다는 것이 책임의 전제이다", "예화_적용": "위험을 알면서도 경고를 무시하는 것이 더 위험하다. 말씀을 알면서도 행하지 않는 것이 더 심각한 문제이다"},
    {"대지": "3대지: 상기시키는 목회의 가치 (반복)", "내용": "바울은 이미 아는 것을 다시 상기시킨다. 상기시키는 목회도 중요하다. 사람은 알아도 잊는다. 반복적으로 상기시키는 것이 실천을 돕는다", "예화_적용": "매일 보는 메모지가 행동을 바꾼다. 반복적으로 상기시키는 설교가 삶을 변화시킨다"},
    {"대지": "결론", "내용": "주 예수로 말미암은 명령을 알고 있는가? 알고 있다면 행하라. 알고 행하는 자가 복이 있다(요 13:17)", "예화_적용": "오늘 내가 이미 알고 있는 말씀 중 실천하지 않은 것이 있는지 점검하라. 그것을 오늘 한 가지 행해보자"}
