  "표5_매튜헨리": [
    {"영어원문": "That each of you should know how to take a wife in sanctification and honour — the body should be governed by sanctity, not by lust.", "한국어번역": "각각 거룩함과 존귀함으로 자기 아내 취할 줄을 알고 — 몸은 욕망이 아닌 거룩함으로 통제되어야 한다.", "핵심통찰": "결혼 안에서의 성적 관계도 거룩함과 존귀함이라는 기준으로 이루어져야 한다"},
    {"영어원문": "Honour — each should esteem the other highly, not using them as a mere instrument of pleasure.", "한국어번역": "존귀함 — 각각은 상대방을 높이 여겨야 한다. 단순한 쾌락의 도구로 사용해서는 안 된다.", "핵심통찰": "배우자는 쾌락의 도구가 아닌 존귀한 사람이다. 이 인식이 결혼을 거룩하게 한다"}
  ],
