    {"대지": "서론", "내용": "결혼은 하나님의 제도이다. 그 안에서도 거룩함과 존귀함이 요구된다. 이방 문화는 배우자를 쾌락의 도구로 보았지만 성경은 존귀한 사람으로 본다. 이 차이가 결혼의 질을 결정한다", "예화_적용": "진품을 소중히 다루고 가품을 함부로 다루듯, 배우자를 귀하게 여기는 것이 성경적 결혼의 특징이다"},
    {"대지": "1대지: 거룩함으로 배우자를 대하는 결혼 (거룩함)", "내용": "결혼 안에서도 거룩함이 기준이다. 거룩함은 결혼 밖에서만이 아니라 결혼 안에서도 요구된다. 배우자에 대한 관계가 하나님을 향한 관계와 연결된다", "예화_적용": "성전을 거룩하게 지키듯 결혼 안의 관계도 거룩하게 지키는 것이 하나님의 뜻이다"},
    {"대지": "2대지: 존귀함으로 배우자를 여기는 결혼 (존귀함)", "내용": "배우자를 존귀하게 여기는 것이 성경적 결혼의 기초이다. 상대방의 가치를 인정하고 귀하게 대하는 것이다. 도구가 아닌 하나님의 형상으로 지음받은 사람이다", "예화_적용": "왕은 왕비를 귀하게 여긴다. 하나님의 자녀인 배우자를 귀하게 여기는 것이 거룩한 결혼이다"},
    {"대지": "3대지: 세상 문화와 구별되는 결혼관 (구별)", "내용": "이방 문화의 성적 방종과 달리 거룩함과 존귀함으로 배우자를 대하는 것이 구별된 삶이다. 결혼 문화에서도 세상과 다른 성경적 기준이 요구된다", "예화_적용": "빛은 어두운 곳에서 더 잘 보인다. 거룩한 결혼이 세상에서 가장 강력한 복음의 증거이다"},
    {"대지": "결론", "내용": "나는 배우자를 거룩함과 존귀함으로 대하고 있는가? 오늘 배우자를 더 존귀하게 대하는 한 가지를 실천해보자", "예화_적용": "오늘 배우자에게 고맙다, 사랑한다는 말을 하자. 그 작은 실천이 거룩한 결혼의 시작이다"}
