    {"영어원문": "Those who know not God know no check to their lusts — it is the knowledge of God that regulates and restrains sinful desires.", "한국어번역": "하나님을 모르는 자들은 욕망을 억제할 줄 모른다 — 하나님 지식이 죄악된 욕망을 규제하고 억제한다.", "핵심통찰": "하나님을 더 깊이 알아갈수록 죄악된 욕망이 약해진다"}
