    {"영어원문": "The Lord is the avenger in all these things — God himself will punish and call to account those who do such wrongs.", "한국어번역": "이 모든 일에 주께서 신원하여 주심이니라 — 하나님 자신이 이런 잘못을 한 자들을 벌하고 책임을 물으실 것이다.", "핵심통찰": "인간의 눈이 보지 못해도 하나님의 눈이 보신다. 하나님의 심판을 두려워하는 것이 죄의 억제력이 된다"}
