    {"교리": "교회 간의 연대", "설명": "마게도냐 전체 형제들을 향한 사랑이 교회 간의 연대를 보여준다. 한 지역 교회가 넓은 공동체를 향한 사랑을 실천하는 것이 성경적 교회론이다", "관련구절": "고후 8:1-5, 롬 15:26-27, 갈 6:10, 히 13:16"}
