    {"구분": "이방 민족을 향한 사랑의 확장", "내용": "룻처럼 이방인도 하나님 백성의 공동체에 포함되는 확장이 구약에서 예시되었다. 마게도냐 형제들에게로 확장되는 사랑이 이 확장의 신약적 완성이다", "그리스도연결": "그리스도는 민족의 경계를 넘어 모든 사람을 사랑하셨다. 이 보편적 사랑이 교회 내 형제 사랑의 확장으로 이어진다"}
