    {"원어": "χρείαν (크레이안)", "의미_문법": "궁핍 - 명사 여성 단수 대격. 필요, 결핍, 부족", "설교포인트": "아무 궁핍함이 없게 하는 것이 손으로 일하는 목적이다. 자족하는 삶이 다른 사람에게 부담을 주지 않고 외인 앞에서 단정하게 행하는 기초이다"}
