    {"구절": "단 12:13", "연결점": "마지막에 일어나 네 분깃을 받을 것 — 죽은 자도 마지막에 부활하는 구약 예언", "구분": "구약"},
    {"구절": "요 5:28-29", "연결점": "무덤 속에 있는 자들이 다 그의 음성을 들을 때 — 죽은 자들의 부활 약속", "구분": "신약"},
    {"구절": "고전 15:23", "연결점": "각각 자기 차례대로 부활 — 부활의 순서", "구분": "신약"},
    {"구절": "롬 8:23-25", "연결점": "소망으로 구원을 얻었으며 보이지 않는 것을 바람 — 부활 소망의 신학", "구분": "신약"},
    {"구절": "히 11:39-40", "연결점": "약속을 받지 못하고 죽은 자들도 우리 없이 온전함을 이루지 못함 — 함께 이루는 구원", "구분": "신약"},
    {"구절": "민 9:9-13", "연결점": "늦은 유월절 — 달리 도착해도 동등하게 참여하는 공평함의 구약 유비", "구분": "구약"}
