    {"상황": "먼저 죽은 사람이 재림을 놓칠까봐 걱정하는 분", "성경원리": "그리스도 안에서 죽은 자들이 먼저 일어난다. 그들이 재림을 놓치는 것이 아니라 오히려 먼저 경험한다", "실제적용": "먼저 죽은 자들의 부활 순서에 대한 성경 말씀을 명확히 가르치라. 걱정 대신 그들을 위한 소망을 갖도록 이끌라"}
