    {"상황": "재림이 두렵고 무서운 분", "성경원리": "재림은 성도들에게 두려운 것이 아닌 주님을 영접하는 기쁨이다. 재림 때 성도들이 주님을 만나러 올라간다", "실제적용": "재림의 두 가지 측면(심판과 구원)을 구별하여 가르치라. 그리스도 안에 있는 자에게 재림은 영접의 기쁨임을 가르치라"}
