    {"구절": "마 24:43", "연결점": "집 주인이 알았더라면 도적이 오지 못했을 것 — 준비된 자에게는 도적이 도적이 아님", "구분": "신약"},
    {"구절": "요일 1:7", "연결점": "빛 가운데 행하면 서로 사귐이 있고 — 빛 안에서의 삶", "구분": "신약"}
