    {"구분": "벨사살의 연회", "내용": "바벨론 왕 벨사살이 연회를 열어 취해있을 때 심판이 임했다(단 5:1-6). 취함과 방탕이 심판 직전의 모습이다. 근신하지 않은 자에게 심판은 갑작스럽게 온다", "그리스도연결": "그리스도의 재림도 예고 없이 온다. 취해있는 자들에게 재림은 심판이 된다. 벨사살의 연회가 재림 앞에서 취해있는 자들의 모습을 예표한다"}
