    {"원어": "εἰρηνεύετε (에이레뉴에테)", "의미_문법": "화목하라 - 동사 현재 능동 명령법 2인칭 복수. 화평을 이루라, 평화를 유지하라는 현재 지속적 명령", "설교포인트": "화목은 일회적 사건이 아닌 지속적인 노력이다. 공동체 안의 화목을 유지하는 것이 성도의 지속적인 책임이다"}
