    {"항목": "16~18절의 완결", "내용": "기뻐하라, 기도하라, 감사하라의 세 명령이 18절에서 완결된다. 이것이 하나님의 뜻이다. 세 명령이 함께 하나님의 뜻을 구성한다. 기쁨과 기도와 감사가 하나님의 뜻을 사는 삶이다", "목회적활용": "이 세 가지를 하나님의 뜻으로 가르치라. 하나님의 뜻을 찾는 많은 성도들에게 이 세 가지가 명확한 하나님의 뜻이다"}
