    {"영어원문": "For this is the will of God in Christ Jesus concerning you — this is an explicit declaration of God's will; many ask what is God's will, and here it is told them plainly.", "한국어번역": "이는 그리스도 예수 안에서 너희를 향하신 하나님의 뜻이니라 — 이것은 하나님의 뜻에 대한 명시적 선언이다. 많은 사람이 하나님의 뜻이 무엇인지 묻는다. 여기서 그것이 분명히 말해진다.", "핵심통찰": "하나님의 뜻을 묻는 자에게 가장 명확한 답이 감사하라이다"}
