    {"새찬송가": "304", "통일찬송가": "226", "제목": "주를 앙모하는 자", "선정이유": "미쁘신 하나님을 앙모하며 그 신실하심을 의지하는 성도의 신앙을 담는다"},
    {"새찬송가": "390", "통일찬송가": "445", "제목": "주님 약속하신 말씀 위에서", "선정이유": "이루시는 하나님의 약속 위에 서는 성도의 믿음을 담는다"},
    {"새찬송가": "337", "통일찬송가": "387", "제목": "내 주의 나라와", "선정이유": "신실하신 하나님의 나라가 반드시 이루어질 것에 대한 소망을 담는다"}
