    {"새찬송가": "235", "통일찬송가": "235", "제목": "주의 말씀 따라", "선정이유": "말씀을 듣고 따르는 성도의 삶을 담는다"},
    {"새찬송가": "540", "통일찬송가": "392", "제목": "빛의 사자들이여", "선정이유": "말씀을 모든 사람에게 전하는 사명을 담는다"},
    {"새찬송가": "283", "통일찬송가": "212", "제목": "참 아름다워라", "선정이유": "말씀의 아름다움을 모든 사람과 나누는 기쁨을 담는다"}
